<?php require_once __DIR__ . '/../includes/functions.php'; admin_header('Case View'); $id=(int)($_GET['id']??0); $case=db_fetch('SELECT pc.*,p.* FROM patient_cases pc JOIN patients p ON p.id=pc.patient_id WHERE pc.id=?',[$id]); if(!$case){ echo empty_state('Case not found.'); admin_footer(); exit; } $messages=db_fetch_all('SELECT * FROM chat_messages WHERE case_id=? ORDER BY id',[$id]); $report=db_fetch('SELECT * FROM ai_case_reports WHERE case_id=? ORDER BY id DESC LIMIT 1',[$id]); ?><div class="row g-3"><div class="col-lg-5"><div class="card soft-card"><div class="card-body"><h3><?= e($case['case_code']) ?></h3><p><?= e($case['full_name']) ?>, <?= e($case['age']) ?>, <?= e($case['gender']) ?></p><p><?= e($case['phone']) ?> / <?= e($case['whatsapp']) ?></p><h5>Form Data</h5><pre class="bg-light p-3 rounded small"><?= e(json_encode_safe(json_decode_safe($case['full_form_json'], []))) ?></pre></div></div></div><div class="col-lg-7"><div class="card soft-card mb-3"><div class="card-body"><h4>Chat History</h4><?php foreach($messages as $m): ?><p><strong><?= e($m['sender_type']) ?>:</strong> <?= nl2br(e($m['message'])) ?></p><?php endforeach; ?></div></div><div class="card soft-card"><div class="card-body"><h4>AI Diagnosis</h4><?php if($report): ?><p><?= nl2br(e($report['diagnosis_summary'])) ?></p><p>Confidence: <?= e((string)$report['confidence_score']) ?></p><a class="btn btn-teal" href="prescription-review.php?case=<?= $id ?>">Review Prescription</a><?php else: ?><?= empty_state('No AI report yet.') ?><?php endif; ?></div></div></div></div><?php admin_footer(); ?>
